mapper.select:
SELECT api_resource_id
FROM iam_role_api
WHERE tenant_id = #{tenantId}
  AND role_id = #{roleId}
  AND deleted = 0
ORDER BY id DESC

mapper.update:
UPDATE iam_role_api
SET deleted = 1, deleted_at = NOW(3), updated_at = NOW(3),
    updated_by = COALESCE(#{actorId}, 0), version = version + 1
WHERE tenant_id = #{tenantId}
  AND role_id = #{roleId}
  AND deleted = 0
